package dev.proofcode.control.data;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import org.springframework.stereotype.Component;
import org.springframework.data.redis.connection.*;
import org.springframework.data.redis.connection.lettuce.*;
import org.springframework.data.redis.core.*;

/** Bounded standalone string management; resource-scoped keys and durable generation metadata. */
@Component
public class RedisDataAdapter implements DataAdapter {
    private final DataSecrets secrets;private final ObjectMapper json;
    public RedisDataAdapter(DataSecrets secrets,ObjectMapper json){this.secrets=secrets;this.json=json;}
    private <T>T with(DataResource r,Function<StringRedisTemplate,T> action){JsonNode s=secrets.resolve(r.secretRef);RedisStandaloneConfiguration c=new RedisStandaloneConfiguration(DataPolicy.required(s,"host"),DataPolicy.integer(s,"port",1,65535,6379));c.setDatabase(DataPolicy.integer(s,"database",0,15,0));if(s.has("username"))c.setUsername(s.get("username").asText());if(s.has("password"))c.setPassword(s.get("password").asText());LettuceClientConfiguration client=s.path("tls").asBoolean()?LettuceClientConfiguration.builder().useSsl().and().commandTimeout(Duration.ofSeconds(5)).build():LettuceClientConfiguration.builder().commandTimeout(Duration.ofSeconds(5)).build();LettuceConnectionFactory factory=new LettuceConnectionFactory(c,client);factory.afterPropertiesSet();factory.start();try{StringRedisTemplate t=new StringRedisTemplate(factory);t.afterPropertiesSet();return action.apply(t);}finally{factory.destroy();}}
    private String prefix(DataResource r){return "pc:{"+r.projectId+":"+r.id+"}:"+r.environment+":";}
    private String key(DataResource r,JsonNode ir){String key=DataPolicy.required(ir,"key");if(key.length()>512||key.chars().anyMatch(ch->ch<32)||key.startsWith("pc:")||key.contains("::pcmeta"))throw DataPolicy.bad("invalid logical cache key");return prefix(r)+key;}
    private String metaKey(String key){return key+"::pcmeta";}
    @Override public JsonNode schema(DataResource r){return json.createObjectNode().put("provider","redis").put("namespace",prefix(r)).put("namespaceVersion",2).put("valueType","string").put("mode","standalone");}
    @Override public Compiled compile(DataResource r,JsonNode ignored,JsonNode ir){
        DataPolicy.fields(ir,"kind","operation","key","value","ttlSeconds","cursor","count");if(!DataPolicy.required(ir,"kind").equals("cache"))throw DataPolicy.bad("invalid cache kind");String op=DataPolicy.required(ir,"operation");if(!Set.of("get","set","delete","expire","scan").contains(op))throw DataPolicy.bad("unsupported cache operation");
        if(op.equals("scan")){if(ir.has("key")||ir.has("value")||ir.has("ttlSeconds"))throw DataPolicy.bad("scan only accepts cursor/count");String cursor=ir.path("cursor").asText("0");if(!cursor.matches("[0-9]{1,20}"))throw DataPolicy.bad("invalid cursor");DataPolicy.integer(ir,"count",1,100,50);}
        else {key(r,ir);if(ir.has("cursor")||ir.has("count"))throw DataPolicy.bad("cursor/count only apply to scan");if(op.equals("set")){if(!ir.path("value").isTextual()||ir.path("value").asText().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw DataPolicy.bad("set requires a string of at most 64 KiB");if(!ir.has("ttlSeconds"))throw DataPolicy.bad("set requires ttlSeconds");DataPolicy.integer(ir,"ttlSeconds",1,86400,-1);}else {if(ir.has("value"))throw DataPolicy.bad("value only applies to set");if(op.equals("expire")){if(!ir.has("ttlSeconds"))throw DataPolicy.bad("expire requires ttlSeconds");DataPolicy.integer(ir,"ttlSeconds",1,86400,-1);}else if(ir.has("ttlSeconds"))throw DataPolicy.bad("TTL only applies to set/expire");}}
        String preview=op.equals("scan")?"SCAN resource namespace (bounded)":op.toUpperCase(Locale.ROOT)+" "+key(r,ir)+(ir.has("ttlSeconds")?" TTL="+ir.get("ttlSeconds").intValue():"")+(op.equals("set")?" valueHash="+DataPolicy.hash(ir.get("value").asText()):"");return new Compiled("cache",preview,"",List.of(),ir);
    }
    private boolean writes(Compiled p){return Set.of("set","delete","expire").contains(p.ir().path("operation").asText());}
    private String valueHash(String value){return DataPolicy.hash(value==null?"absent":"present:"+value);}
    private JsonNode metadata(String raw){if(raw==null)return json.createObjectNode().put("generation",0);try{JsonNode n=json.readTree(raw);if(!n.isObject()||!n.path("generation").isIntegralNumber()||n.path("generation").asLong()<1)throw new IllegalArgumentException();return n;}catch(Exception e){throw DataPolicy.bad("cache generation metadata is invalid");}}
    private ObjectNode snapshot(StringRedisTemplate t,String key){DataType type=t.type(key);if(type!=DataType.NONE&&type!=DataType.STRING)throw DataPolicy.bad("only string cache values are supported");String value=t.opsForValue().get(key),raw=t.opsForValue().get(metaKey(key));Long ttl=t.getExpire(key,TimeUnit.MILLISECONDS);if(value!=null&&value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw DataPolicy.bad("cache snapshot is too large");JsonNode meta=metadata(raw);if(value!=null&&raw==null)throw DataPolicy.bad("unmanaged cache state has no trusted generation");if(value!=null&&!meta.path("hash").asText().equals(valueHash(value)))throw DataPolicy.bad("cache state changed outside the managed gateway");ObjectNode n=json.createObjectNode();if(value==null)n.putNull("value");else n.put("value",value);n.put("hash",valueHash(value)).put("ttlMs",ttl==null?-2:ttl).put("expiresAt",ttl!=null&&ttl>=0?System.currentTimeMillis()+ttl:-1).put("generation",meta.path("generation").asLong()).put("metadataHash",DataPolicy.hash(raw==null?"absent":raw));return n;}
    private JsonNode recovery(String s){try{return json.readTree(secrets.unseal(s));}catch(Exception e){throw DataPolicy.bad("invalid cache recovery snapshot");}}
    @Override public String prepare(DataResource r,Compiled p){if(!writes(p))return null;return with(r,t->{ObjectNode n=snapshot(t,key(r,p.ir()));n.put("key",key(r,p.ir())).put("resourceId",r.id.toString()).put("resourceVersion",r.resourceVersion).put("snapshotExpiresAt",System.currentTimeMillis()+7L*86400000L);return secrets.seal(n.toString());});}
    @Override public Outcome execute(DataResource r,Compiled p){return execute(r,p,prepare(r,p));}
    @Override public Outcome execute(DataResource r,Compiled p,String encrypted){
        try{return with(r,t->{String op=p.ir().path("operation").asText();if(op.equals("scan"))return scan(r,p,t);
            String key=key(r,p.ir());if(op.equals("get")){ObjectNode snap=snapshot(t,key);Map<String,Object> result=new LinkedHashMap<>();result.put("value",snap.path("value").isNull()?null:snap.path("value").asText());result.put("type",snap.path("value").isNull()?"none":"string");result.put("sizeBytes",snap.path("value").isNull()?0:snap.path("value").asText().getBytes(java.nio.charset.StandardCharsets.UTF_8).length);result.put("ttlMs",snap.path("ttlMs").asLong());result.put("hash",snap.path("hash").asText());result.put("generation",snap.path("generation").asLong());result.put("readAt",Instant.now().toString());return new Outcome("SUCCEEDED",result,null);}
            JsonNode before=recovery(encrypted);if(!before.path("resourceId").asText().equals(r.id.toString())||before.path("resourceVersion").asLong(-1)!=r.resourceVersion||!before.path("key").asText().equals(key))return new Outcome("FAILED_PRECONDITION",Map.of("errorCode","CACHE_SNAPSHOT_SCOPE"),null);
            long generation=Math.addExact(before.path("generation").asLong(),1);String postValue=op.equals("delete")?null:op.equals("set")?p.ir().path("value").asText():before.path("value").isNull()?null:before.path("value").asText();long afterExpiry=postValue==null?-1:System.currentTimeMillis()+p.ir().path("ttlSeconds").asLong()*1000;String writeId=UUID.randomUUID().toString();String nextMeta=json.createObjectNode().put("generation",generation).put("hash",valueHash(postValue)).put("expiresAt",afterExpiry).put("writeId",writeId).toString();
            Boolean success=t.execute(new SessionCallback<Boolean>(){@Override @SuppressWarnings("unchecked") public <K,V> Boolean execute(RedisOperations<K,V> operations){RedisOperations<String,String> ops=(RedisOperations<String,String>)(RedisOperations<?,?>)operations;ops.watch(List.of(key,metaKey(key)));String current=ops.opsForValue().get(key),raw=ops.opsForValue().get(metaKey(key));Long ttl=ops.getExpire(key,TimeUnit.MILLISECONDS);if(!matches(before,current,ttl,raw)){ops.unwatch();return false;}ops.multi();if(op.equals("set"))ops.opsForValue().set(key,p.ir().path("value").asText(),Duration.ofSeconds(p.ir().path("ttlSeconds").asLong()));else if(op.equals("delete"))ops.delete(key);else ops.expire(key,Duration.ofSeconds(p.ir().path("ttlSeconds").asLong()));ops.opsForValue().set(metaKey(key),nextMeta);List<Object> results=ops.exec();if(results==null||results.isEmpty())return false;for(Object value:results)if(value instanceof Exception)throw new IllegalStateException("Redis EXEC returned an error");return true;}});
            if(!Boolean.TRUE.equals(success))return Outcome.failed("CACHE_CAS_CONFLICT");ObjectNode snap=(ObjectNode)before.deepCopy();snap.put("afterHash",valueHash(postValue)).put("afterExpiresAt",afterExpiry).put("afterGeneration",generation).put("afterWriteId",writeId).put("afterMetadataHash",DataPolicy.hash(nextMeta));int affected=op.equals("set")||!before.path("value").isNull()?1:0;return new Outcome("COMMITTED",Map.of("affectedKeys",affected,"beforeHash",before.path("hash").asText(),"beforeTtlMs",before.path("ttlMs").asLong(),"afterHash",valueHash(postValue),"generation",generation,"recoveryAvailable",true),secrets.seal(snap.toString()));
        });}catch(Exception e){return new Outcome("COMMIT_UNKNOWN",Map.of("errorCode","CACHE_RESULT_UNKNOWN"),encrypted);}
    }
    private Outcome scan(DataResource r,Compiled p,StringRedisTemplate t){List<String> keys=new ArrayList<>();List<Map<String,Object>> entries=new ArrayList<>();int count=DataPolicy.integer(p.ir(),"count",1,100,50);String cursor=p.ir().path("cursor").asText("0");try(RedisConnection c=Objects.requireNonNull(t.getConnectionFactory()).getConnection()){
        Object nativeConnection=c.getNativeConnection();if(!(nativeConnection instanceof io.lettuce.core.api.async.RedisAsyncCommands<?,?>))throw new IllegalStateException("SCAN requires standalone Lettuce");@SuppressWarnings("unchecked") io.lettuce.core.api.async.RedisAsyncCommands<byte[],byte[]> commands=(io.lettuce.core.api.async.RedisAsyncCommands<byte[],byte[]>)nativeConnection;io.lettuce.core.KeyScanCursor<byte[]> page=commands.scan(io.lettuce.core.ScanCursor.of(cursor),new io.lettuce.core.ScanArgs().match(prefix(r)+"*").limit(count)).get(5,TimeUnit.SECONDS);
        int size=0;for(byte[] raw:page.getKeys()){String key=new String(raw,java.nio.charset.StandardCharsets.UTF_8);if(!key.startsWith(prefix(r))||key.endsWith("::pcmeta"))continue;size+=raw.length;if(size>262144||keys.size()>=1000)throw new IllegalStateException("bounded SCAN page exceeded");String logical=key.substring(prefix(r).length());keys.add(logical);DataType type=t.type(key);Long ttl=t.getExpire(key,TimeUnit.MILLISECONDS),bytes=type==DataType.STRING?t.opsForValue().size(key):null;Map<String,Object> entry=new LinkedHashMap<>();entry.put("key",logical);entry.put("type",type==null?"none":type.code());entry.put("ttlMs",ttl==null?-2:ttl);entry.put("sizeBytes",bytes);entry.put("readAt",Instant.now().toString());entries.add(entry);}return new Outcome("SUCCEEDED",Map.of("keys",keys,"entries",entries,"cursor",page.getCursor()),null);
    }catch(Exception e){return new Outcome("FAILED_PRECONDITION",Map.of("errorCode","CACHE_SCAN_FAILED"),null);}}
    private boolean matches(JsonNode before,String value,Long ttl,String raw){if(!before.path("metadataHash").asText().equals(DataPolicy.hash(raw==null?"absent":raw))||!before.path("hash").asText().equals(valueHash(value)))return false;long expected=before.path("expiresAt").asLong(-1);if(expected<0)return before.path("ttlMs").asLong(-2)==(ttl==null?-2:ttl);return ttl!=null&&ttl>=0&&Math.abs(System.currentTimeMillis()+ttl-expected)<=200;}
    @Override public Outcome compensate(DataResource r,String encrypted){try{return with(r,t->{JsonNode snap=recovery(encrypted);String key=DataPolicy.required(snap,"key");if(!key.startsWith(prefix(r))||!snap.path("resourceId").asText().equals(r.id.toString())||snap.path("resourceVersion").asLong(-1)!=r.resourceVersion||snap.path("snapshotExpiresAt").asLong(0)<=System.currentTimeMillis())return new Outcome("COMPENSATION_CONFLICT",Map.of("errorCode","RECOVERY_SCOPE_OR_EXPIRY"),null);
        Boolean ok=t.execute(new SessionCallback<Boolean>(){@Override @SuppressWarnings("unchecked") public <K,V> Boolean execute(RedisOperations<K,V> operations){RedisOperations<String,String> ops=(RedisOperations<String,String>)(RedisOperations<?,?>)operations;ops.watch(List.of(key,metaKey(key)));String current=ops.opsForValue().get(key),raw=ops.opsForValue().get(metaKey(key));Long ttl=ops.getExpire(key,TimeUnit.MILLISECONDS);long afterExpiry=snap.path("afterExpiresAt").asLong(-1);if(raw==null||!snap.path("afterMetadataHash").asText().equals(DataPolicy.hash(raw))||!snap.path("afterHash").asText().equals(valueHash(current))||(current!=null&&afterExpiry>=0&&(ttl==null||ttl<0||Math.abs(System.currentTimeMillis()+ttl-afterExpiry)>200))){ops.unwatch();return false;}long oldExpiry=snap.path("expiresAt").asLong(-1);if(oldExpiry>=0&&oldExpiry<=System.currentTimeMillis()){ops.unwatch();return false;}long generation=Math.addExact(snap.path("afterGeneration").asLong(),1);String restored=snap.path("value").isNull()?null:snap.path("value").asText();String meta=json.createObjectNode().put("generation",generation).put("hash",valueHash(restored)).put("expiresAt",oldExpiry).put("writeId",UUID.randomUUID().toString()).toString();ops.multi();if(restored==null)ops.delete(key);else if(oldExpiry>=0)ops.opsForValue().set(key,restored,Duration.ofMillis(oldExpiry-System.currentTimeMillis()));else ops.opsForValue().set(key,restored);ops.opsForValue().set(metaKey(key),meta);List<Object> result=ops.exec();return result!=null&&!result.isEmpty()&&result.stream().noneMatch(Exception.class::isInstance);}});return new Outcome(Boolean.TRUE.equals(ok)?"COMPENSATED":"COMPENSATION_CONFLICT",Map.of("restored",Boolean.TRUE.equals(ok)),null);
        });}catch(Exception e){return new Outcome("COMPENSATION_UNKNOWN",Map.of("errorCode","CACHE_COMPENSATION_UNKNOWN"),null);}}
}
